<?php $url = static fn(string $parent = ''): string => '/files?' . http_build_query(['space' => $data['space']['id'], 'parent' => $parent]); ?>
<div class="page-heading"><div><p class="eyebrow">DATEIABLAGE</p><h1><?= $e($data['folder']['name'] ?? $data['space']['name']) ?></h1><p class="lead"><?= $e($data['space']['name']) ?> · <?= $e(number_format($data['used'] / 1048576, 2, ',', '.')) ?> / <?= $e(number_format((int) $data['space']['quota_bytes'] / 1048576, 0, ',', '.')) ?> MiB</p></div><a class="button button-outline" href="/files">Alle Bereiche</a></div>
<?php if ($data['folder'] !== null): ?><p><a href="<?= $e($url($data['folder']['parent_id'])) ?>">Übergeordneter Ordner</a> · <a href="<?= $e($url()) ?>">Bereichswurzel</a></p><?php endif ?>
<?php if ($data['can_create']): ?><section class="panel create-panel"><form method="post" action="/files/folder"><h2>Ordner anlegen</h2><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space']['id']) ?>"><input type="hidden" name="parent" value="<?= $e($data['parent']) ?>"><label for="folder-name">Ordnername</label><div class="input-action"><input id="folder-name" name="name" required maxlength="255"><button class="button" type="submit">Anlegen</button></div></form>
<form method="post" action="/files/upload" enctype="multipart/form-data"><h2>Datei hochladen</h2><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space']['id']) ?>"><input type="hidden" name="parent" value="<?= $e($data['parent']) ?>"><label for="upload-file">Datei, maximal <?= $e(number_format($data['upload_max_bytes'] / 1048576, 2, ',', '.')) ?> MiB</label><input id="upload-file" type="file" name="file" required><button class="button" type="submit">Hochladen</button><p class="field-note">Vorhandene Dateien werden nicht überschrieben. Der Server kann eine niedrigere Uploadgrenze vorgeben.</p></form></section><?php endif ?>
<?php if ($data['can_view_trash']): ?><p><a href="/files/trash?space=<?= $e(rawurlencode($data['space']['id'])) ?>">Papierkorb öffnen</a></p><?php endif ?>
<section class="panel"><div class="panel-heading"><h2>Inhalt</h2><span class="subtle">Bis zu 100 Einträge pro Seite</span></div><div class="group-list">
<?php foreach ($data['rows'] as $row): ?><article class="group-row"><div><h3><?php if ($row['kind'] === 'folder'): ?><a href="<?= $e($url($row['id'])) ?>"><?= $e($row['name']) ?></a><?php else: ?><?= $e($row['name']) ?><?php endif ?></h3><p class="subtle"><?= $row['kind'] === 'folder' ? 'Ordner' : $e(number_format((int) $row['size_bytes'], 0, ',', '.')) . ' Bytes' ?></p><a href="<?= $e('/files/detail?' . http_build_query(['space' => $data['space']['id'], 'entry' => $row['id']])) ?>">Eintrag verwalten</a></div><?php if ($row['kind'] === 'file' && $data['can_read']): ?><a class="button button-outline" href="<?= $e('/files/download?' . http_build_query(['space' => $data['space']['id'], 'entry' => $row['id']])) ?>">Herunterladen</a><?php endif ?></article><?php endforeach ?>
<?php if ($data['rows'] === []): ?><p class="empty">Dieser Ordner ist leer.</p><?php endif ?></div>
<?php if ($data['next'] !== null): ?><div class="panel-foot"><a href="<?= $e($url($data['parent']) . '&after=' . rawurlencode($data['next'])) ?>">Weitere Einträge</a></div><?php endif ?></section>
